import express from "express";

const app = express();
const port = Number(process.env.PORT ?? 3000);

app.get("/api/hello", (_req, res) => {
  res.json({ message: "Hello from Express" });
});

app.listen(port, () => {
  console.log(`API listening on http://localhost:${port}`);
});

