import Fastify from "fastify";

const app = Fastify({ logger: true });
const port = Number(process.env.PORT ?? 3000);

app.get("/api/hello", async () => ({ message: "Hello from Fastify" }));

app.listen({ port }).catch((err) => {
  app.log.error(err);
  process.exit(1);
});

